package dev.dailycareer.ai;
import com.fasterxml.jackson.databind.JsonNode;import dev.dailycareer.common.api.*;import dev.dailycareer.common.idempotency.IdempotencyService;import dev.dailycareer.common.json.Ids;import dev.dailycareer.user.AppPrincipal;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.ResponseEntity;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/ai") public class AiController{private final AiService service;AiController(AiService service){this.service=service;}
 @PostMapping("/explanations")ResponseEntity<?> explanation(@AuthenticationPrincipal AppPrincipal p,@RequestBody JsonNode b,HttpServletRequest r){return create(p,"AI-001","EXPLANATION",b,r);}@PostMapping("/practice-problems")ResponseEntity<?> practice(@AuthenticationPrincipal AppPrincipal p,@RequestBody JsonNode b,HttpServletRequest r){return create(p,"AI-002","PRACTICE_PROBLEMS",b,r);}@PostMapping("/wrong-answer-reviews")ResponseEntity<?> wrong(@AuthenticationPrincipal AppPrincipal p,@RequestBody JsonNode b,HttpServletRequest r){return create(p,"AI-003","WRONG_ANSWER_REVIEW",b,r);}@PostMapping("/daily-feedback")ResponseEntity<?> daily(@AuthenticationPrincipal AppPrincipal p,@RequestBody JsonNode b,HttpServletRequest r){return create(p,"AI-004","DAILY_FEEDBACK",b,r);}@PostMapping("/monthly-reviews")ResponseEntity<?> monthly(@AuthenticationPrincipal AppPrincipal p,@RequestBody JsonNode b,HttpServletRequest r){return create(p,"AI-005","MONTHLY_REVIEW",b,r);}
 @GetMapping("/jobs/{id}")ResponseEntity<?> get(@AuthenticationPrincipal AppPrincipal p,@PathVariable String id,HttpServletRequest r){return ApiResponses.ok(r,service.get(user(p),Ids.parse(id)));}@GetMapping("/jobs")ResponseEntity<?> list(@AuthenticationPrincipal AppPrincipal p,@RequestParam(required=false)String purpose,@RequestParam(required=false)String status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,HttpServletRequest r){return ApiResponses.ok(r,service.list(user(p),purpose,status,page,size));}@GetMapping("/usage")ResponseEntity<?> usage(@AuthenticationPrincipal AppPrincipal p,HttpServletRequest r){return ApiResponses.ok(r,service.usage(user(p)));}
 private ResponseEntity<?>create(AppPrincipal p,String op,String purpose,JsonNode b,HttpServletRequest r){return service.create(user(p),op,purpose,b,IdempotencyService.requiredKey(r)).toResponse(r);}private static long user(AppPrincipal p){if(p==null)throw new ApiException(ApiErrorCode.AUTH_REQUIRED);return p.userId();}}
